/* BattleQuiz - Sports (Formula 1 only).
 * Each entry carries both languages; `c` is the index of the correct option
 * in BOTH arrays, and `d` is the difficulty level 1-8.
 */
window.BANK = window.BANK || [];
window.BANK.push(
  { id:"spo001", t:"sport", d:1, c:0, en:{q:"What kind of vehicle races in Formula 1?",a:["A racing car","A boat","An aeroplane","A bicycle"]}, tr:{q:"Formula 1'de hangi araç yarışır?",a:["Yarış arabası","Tekne","Uçak","Bisiklet"]}, ex:{en:"Formula 1 cars are single-seat racing cars built purely for speed on closed circuits.",tr:"Formula 1 arabaları, kapalı pistlerde hız için üretilmiş tek koltuklu yarış arabalarıdır."} },
  { id:"spo002", t:"sport", d:1, c:0, en:{q:"In football, which player is allowed to catch the ball with their hands?",a:["The goalkeeper","The striker","The defender","The team captain"]}, tr:{q:"Futbolda hangi oyuncu topu elleriyle tutabilir?",a:["Kaleci","Forvet","Defans oyuncusu","Takım kaptanı"]}, ex:{en:"The goalkeeper is the only player allowed to use their hands, and only inside their own penalty area.",tr:"Kaleci, ellerini kullanmasına izin verilen tek oyuncudur ve bunu yalnızca kendi ceza sahası içinde yapabilir."} },
  { id:"spo003", t:"sport", d:1, c:0, en:{q:"What do tennis players hit the ball with?",a:["A racket","A baseball bat","A golf club","A hockey stick"]}, tr:{q:"Tenisçiler topa neyle vurur?",a:["Raketle","Beyzbol sopasıyla","Golf sopasıyla","Hokey sopasıyla"]}, ex:{en:"A tennis racket's strung head lets players strike the ball with speed and control.",tr:"Tenis raketinin telli başlığı, oyunculara topa hızlı ve kontrollü vurma imkânı verir."} },
  { id:"spo004", t:"sport", d:1, c:0, en:{q:"At the Olympics, which medal does the winner of a race get?",a:["A gold medal","A silver medal","A bronze medal","A wooden medal"]}, tr:{q:"Olimpiyatlarda bir yarışı kazanan sporcu hangi madalyayı alır?",a:["Altın madalya","Gümüş madalya","Bronz madalya","Tahta madalya"]}, ex:{en:"Olympic winners receive gold; second place gets silver, and third gets bronze.",tr:"Olimpiyat'ta birinciye altın, ikinciye gümüş, üçüncüye ise bronz madalya verilir."} },
  { id:"spo005", t:"sport", d:1, c:0, en:{q:"In the high jump, what do athletes jump over?",a:["A bar","A rope","A wall","A river"]}, tr:{q:"Yüksek atlamada sporcular neyin üzerinden atlar?",a:["Çıta","İp","Duvar","Nehir"]}, ex:{en:"High jumpers run up and leap over a raised bar without knocking it off its supports.",tr:"Yüksek atlamacılar koşarak yükselir ve barı desteklerinden düşürmeden üzerinden atlar."} },
  { id:"spo006", t:"sport", d:1, c:0, en:{q:"In a Formula 1 race, which vehicle do the drivers use?",a:["Racing cars","Bicycles","Boats","Motorbikes"]}, tr:{q:"Formula 1 yarışında pilotlar hangi aracı kullanır?",a:["Yarış arabası","Bisiklet","Tekne","Motosiklet"]}, ex:{en:"Formula 1 drivers race single-seat cars specially built for maximum speed.",tr:"Formula 1 pilotları, maksimum hız için özel üretilmiş tek koltuklu arabalarla yarışır."} },
  { id:"spo007", t:"sport", d:1, c:0, en:{q:"In golf, where do players try to send the little ball?",a:["Into a small hole","Into a goal","Into a net","Into a basket"]}, tr:{q:"Golfte oyuncular küçük topu nereye sokmaya çalışır?",a:["Küçük bir deliğe","Kaleye","Fileye","Sepete"]}, ex:{en:"In golf, the aim is to hit the ball into a small hole using as few strokes as possible.",tr:"Golfte amaç, topu mümkün olduğunca az vuruşla küçük bir deliğe sokmaktır."} },
  { id:"spo008", t:"sport", d:1, c:0, en:{q:"In volleyball, what do players hit the ball over?",a:["A net","A wall","A fence","A goal"]}, tr:{q:"Voleybolda oyuncular topu neyin üzerinden geçirir?",a:["File","Duvar","Çit","Kale"]}, ex:{en:"Volleyball players hit the ball back and forth over a net stretched across the court.",tr:"Voleybolcular, sahanın ortasına gerilmiş bir filenin üzerinden topu karşılıklı gönderir."} },
  { id:"spo009", t:"sport", d:1, c:0, en:{q:"How many players play a game of chess?",a:["Two players","Three players","Four players","Six players"]}, tr:{q:"Bir satranç oyununu kaç kişi oynar?",a:["İki kişi","Üç kişi","Dört kişi","Altı kişi"]}, ex:{en:"Chess is a game for exactly two players, each controlling their own set of pieces.",tr:"Satranç, her biri kendi taş takımını yöneten tam olarak iki oyuncu için bir oyundur."} },
  { id:"spo010", t:"sport", d:1, c:0, en:{q:"What do boxers wear on their hands?",a:["Gloves","Socks","Hats","Scarves"]}, tr:{q:"Boksörler ellerine ne takar?",a:["Eldiven","Çorap","Şapka","Atkı"]}, ex:{en:"Boxers wear padded gloves to protect their hands and soften the force of their punches.",tr:"Boksörler, ellerini korumak ve yumruklarının etkisini yumuşatmak için dolgulu eldiven giyer."} },
  { id:"spo011", t:"sport", d:1, c:0, en:{q:"In show jumping, which animal jumps over the fences?",a:["A horse","A dog","A cow","A goat"]}, tr:{q:"Engel atlama sporunda engelleri hangi hayvan atlar?",a:["At","Köpek","İnek","Keçi"]}, ex:{en:"In show jumping, a rider guides a horse over a course of fences without knocking any rails down.",tr:"Engel atlamada binici, atını hiçbir çubuğu düşürmeden bir engel parkurunun üzerinden yönlendirir."} },
  { id:"spo012", t:"sport", d:1, c:0, en:{q:"In football, what is it called when the ball goes into the net?",a:["A goal","A basket","A serve","A smash"]}, tr:{q:"Futbolda top ağlara girdiğinde buna ne denir?",a:["Gol","Basket","Servis","Smaç"]}, ex:{en:"A goal is scored the moment the whole ball crosses the goal line between the posts.",tr:"Top, kaleler arasındaki çizgiyi bütünüyle geçtiği anda gol sayılır."} },
  { id:"spo013", t:"sport", d:1, c:0, en:{q:"Which of these sports is played with a big orange ball?",a:["Basketball","Tennis","Golf","Ice hockey"]}, tr:{q:"Bu sporlardan hangisi büyük turuncu bir topla oynanır?",a:["Basketbol","Tenis","Golf","Buz hokeyi"]}, ex:{en:"Basketball is played with a large orange ball, bounced and thrown towards a raised hoop.",tr:"Basketbol, sektirilip yüksekteki bir potaya atılan büyük turuncu bir topla oynanır."} },
  { id:"spo014", t:"sport", d:1, c:0, en:{q:"In volleyball, which part of the body do players mostly hit the ball with?",a:["Their hands","Their head","Their feet","Their back"]}, tr:{q:"Voleybolda oyuncular topa çoğunlukla neresiyle vurur?",a:["Elleriyle","Kafasıyla","Ayaklarıyla","Sırtıyla"]}, ex:{en:"Volleyball players may only use their hands and arms; kicking the ball is not allowed.",tr:"Voleybolcular sadece ellerini ve kollarını kullanabilir; topa ayakla vurmak yasaktır."} },
  { id:"spo015", t:"sport", d:1, c:0, en:{q:"How many wheels does a racing bicycle have?",a:["Two","Three","One","Four"]}, tr:{q:"Bir yarış bisikletinin kaç tekerleği vardır?",a:["İki","Üç","Bir","Dört"]}, ex:{en:"Like almost every bicycle, a racing bike has two wheels, front and back.",tr:"Neredeyse tüm bisikletler gibi, bir yarış bisikletinin de önde ve arkada olmak üzere iki tekerleği vardır."} },
  { id:"spo016", t:"sport", d:1, c:0, en:{q:"What do skiers hold in their hands as they come down the slope?",a:["Ski poles","A tennis racket","An umbrella","A rope"]}, tr:{q:"Kayakçılar yamaçtan inerken ellerinde ne tutar?",a:["Kayak batonu","Tenis raketi","Şemsiye","İp"]}, ex:{en:"Ski poles help skiers push off, turn and keep their balance while going downhill.",tr:"Kayak batonları, kayakçının itiş almasına, dönmesine ve inişte dengesini korumasına yardımcı olur."} },
  { id:"spo017", t:"sport", d:1, c:0, en:{q:"In Turkish oil wrestling, what do the wrestlers rub on their bodies?",a:["Olive oil","Milk","Sand","Honey"]}, tr:{q:"Yağlı güreşte pehlivanlar vücutlarına ne sürer?",a:["Zeytinyağı","Süt","Kum","Bal"]}, ex:{en:"Wrestlers in Turkish oil wrestling coat their bodies in olive oil, making holds much harder to grip.",tr:"Türk yağlı güreşinde pehlivanlar vücutlarını zeytinyağıyla kaplar, bu da tutuşları çok zorlaştırır."} },
  { id:"spo018", t:"sport", d:1, k:"tf", v:false, en:{q:"In a football match, the two teams wear the same colour shirts as each other."}, tr:{q:"Bir futbol maçında iki takım birbiriyle aynı renk forma giyer."}, ex:{en:"The two teams wear different coloured shirts so players and the referee can tell them apart at a glance.",tr:"İki takım, oyuncuların ve hakemin bir bakışta ayırt edebilmesi için farklı renkte formalar giyer."} },
  { id:"spo019", t:"sport", d:1, k:"tf", v:true, en:{q:"In basketball, players score points by throwing the ball into the basket."}, tr:{q:"Basketbolda oyuncular topu potaya atarak sayı kazanır."}, ex:{en:"A basket, worth two or three points, is scored by getting the ball through the hoop.",tr:"İki veya üç sayılık basket, topu potadan geçirerek atılır."} },
  { id:"spo020", t:"sport", d:1, k:"tf", v:true, en:{q:"In the long jump, athletes land in a pit filled with sand."}, tr:{q:"Uzun atlamada sporcular kumla dolu bir çukura iner."}, ex:{en:"Long jumpers land in a sand pit, which cushions the fall and shows exactly where they landed.",tr:"Uzun atlamacılar bir kum çukuruna iner; bu hem düşüşü yumuşatır hem de tam nereye indiklerini gösterir."} },
  { id:"spo021", t:"sport", d:1, k:"tf", v:true, en:{q:"Swimmers wear goggles to keep the water out of their eyes."}, tr:{q:"Yüzücüler, suyun gözlerine kaçmaması için yüzücü gözlüğü takar."}, ex:{en:"Swimming goggles form a watertight seal around the eyes so swimmers can see clearly underwater.",tr:"Yüzücü gözlükleri gözlerin etrafında su geçirmez bir conta oluşturur, böylece su altında net görülebilir."} },
  { id:"spo022", t:"sport", d:1, k:"tf", v:false, en:{q:"In table tennis, players hit the ball with their hands."}, tr:{q:"Masa tenisinde oyuncular topa elleriyle vurur."}, ex:{en:"Table tennis players hit the ball with a small paddle called a bat, not with their bare hands.",tr:"Masa tenisi oyuncuları topa çıplak elle değil, raket denilen küçük bir aletle vurur."} },
  { id:"spo023", t:"sport", d:2, c:0, en:{q:"When the track is wet with rain, which tyres do the teams fit?",a:["Wet tyres with grooves","Smooth dry tyres","Bicycle tyres","Snow chains"]}, tr:{q:"Pist yağmurdan ıslakken takımlar hangi lastikleri takar?",a:["Kanallı yağmur lastikleri","Düz kuru hava lastikleri","Bisiklet lastikleri","Kar zinciri"]}, ex:{en:"Wet tyres have grooves cut into them that channel water away, giving grip on a soaked track.",tr:"Islak lastiklerin üzerinde suyu uzaklaştıran oyuklar bulunur, bu da ıslak pistte tutuş sağlar."} },
  { id:"spo024", t:"sport", d:2, c:0, en:{q:"In basketball, what must you do with the ball while you are running with it?",a:["Bounce it on the floor","Kick it along","Hold it under your arm","Throw it at the wall"]}, tr:{q:"Basketbolda topla koşarken topa ne yapman gerekir?",a:["Topu yere sektirmek","Topa ayakla vurmak","Topu kolunun altında taşımak","Topu duvara atmak"]}, ex:{en:"A player moving with the ball must keep bouncing it, called dribbling, or it counts as a violation.",tr:"Topla hareket eden bir oyuncu, sektirmeye devam etmelidir; buna dripling denir, aksi hâlde ihlal sayılır."} },
  { id:"spo025", t:"sport", d:2, c:0, en:{q:"At the Olympic Games, which medal does the winner of an event receive?",a:["A gold medal","A silver medal","A bronze medal","A copper medal"]}, tr:{q:"Olimpiyat Oyunları'nda bir yarışmayı kazanan hangi madalyayı alır?",a:["Altın madalya","Gümüş madalya","Bronz madalya","Bakır madalya"]}, ex:{en:"Olympic gold goes to first place, with silver for second and bronze for third.",tr:"Olimpiyat'ta altın birinciye, gümüş ikinciye, bronz da üçüncüye verilir."} },
  { id:"spo026", t:"sport", d:2, c:0, en:{q:"In a car race, which flag is waved as the winner crosses the finish line?",a:["A black and white chequered flag","A red flag","A yellow flag","A blue flag"]}, tr:{q:"Otomobil yarışlarında kazanan bitiş çizgisini geçerken hangi bayrak sallanır?",a:["Siyah beyaz damalı bayrak","Kırmızı bayrak","Sarı bayrak","Mavi bayrak"]}, ex:{en:"A black and white chequered flag is waved to mark the moment the race finishes.",tr:"Yarışın bittiği anı belirtmek için siyah beyaz damalı bayrak sallanır."} },
  { id:"spo027", t:"sport", d:2, c:0, en:{q:"What do cyclists wear on their head to keep safe?",a:["A helmet","A crown","A scarf","A towel"]}, tr:{q:"Bisikletçiler güvenlik için başlarına ne takar?",a:["Kask","Taç","Atkı","Havlu"]}, ex:{en:"A helmet protects a cyclist's head from injury in the event of a fall.",tr:"Kask, bir düşme durumunda bisikletçinin kafasını yaralanmadan korur."} },
  { id:"spo028", t:"sport", d:2, c:0, en:{q:"What does a referee blow to stop the game?",a:["A whistle","A trumpet","A horn","A flute"]}, tr:{q:"Hakem oyunu durdurmak için neyi çalar?",a:["Düdük","Trompet","Korna","Flüt"]}, ex:{en:"A referee's whistle signals fouls, goals and stoppages so every player hears it over the noise.",tr:"Hakemin düdüğü faulleri, golleri ve durmaları bildirir; gürültü içinde herkes duyabilsin diye çalınır."} },
  { id:"spo029", t:"sport", d:2, c:0, en:{q:"Which sport is also known as ping pong?",a:["Table tennis","Badminton","Squash","Volleyball"]}, tr:{q:"Pinpon olarak da bilinen spor hangisidir?",a:["Masa tenisi","Badminton","Squash","Voleybol"]}, ex:{en:"Table tennis is nicknamed ping pong after the sound the ball makes bouncing on the table.",tr:"Masa tenisine, topun masada seken sesinden ötürü ping pong lakabı takılmıştır."} },
  { id:"spo030", t:"sport", d:2, c:0, en:{q:"In which sport do athletes perform on a balance beam?",a:["Gymnastics","Judo","Fencing","Archery"]}, tr:{q:"Sporcular hangi sporda denge aleti üzerinde hareket yapar?",a:["Jimnastik","Judo","Eskrim","Okçuluk"]}, ex:{en:"The balance beam is a narrow raised bar that gymnasts perform flips and turns on.",tr:"Denge aleti, jimnastikçilerin üzerinde takla ve dönüş yaptığı dar ve yüksek bir çubuktur."} },
  { id:"spo031", t:"sport", d:2, c:0, en:{q:"What do ice hockey players wear on their feet?",a:["Ice skates","Running shoes","Football boots","Swimming flippers"]}, tr:{q:"Buz hokeyi oyuncuları ayaklarına ne giyer?",a:["Buz pateni","Koşu ayakkabısı","Futbol kramponu","Yüzücü paleti"]}, ex:{en:"Ice hockey players wear ice skates with sharp blades to glide quickly across the rink.",tr:"Buz hokeyi oyuncuları, buz pistinde hızlıca kayabilmek için keskin bıçaklı buz patenleri giyer."} },
  { id:"spo032", t:"sport", d:2, c:0, en:{q:"In football, how many players does each team have on the pitch?",a:["Eleven","Nine","Seven","Thirteen"]}, tr:{q:"Futbolda her takımın sahada kaç oyuncusu bulunur?",a:["On bir","Dokuz","Yedi","On üç"]}, ex:{en:"Each football team fields eleven players on the pitch, including the goalkeeper.",tr:"Her futbol takımı, kaleci dahil sahada on bir oyuncu bulundurur."} },
  { id:"spo033", t:"sport", d:2, c:0, en:{q:"Which sport do teams play in the NBA?",a:["Basketball","Ice hockey","Baseball","Volleyball"]}, tr:{q:"NBA'de takımlar hangi sporu oynar?",a:["Basketbol","Buz hokeyi","Beyzbol","Voleybol"]}, ex:{en:"The NBA is the top professional basketball league in the United States.",tr:"NBA, Amerika Birleşik Devletleri'nin en üst düzey profesyonel basketbol ligidir."} },
  { id:"spo034", t:"sport", d:2, c:0, en:{q:"In volleyball, what is it called when a player jumps and hits the ball hard into the other court?",a:["A spike","A serve","A block","A dig"]}, tr:{q:"Voleybolda bir oyuncunun zıplayıp topa sert vurarak karşı sahaya göndermesine ne denir?",a:["Smaç","Servis","Blok","Manşet"]}, ex:{en:"A spike is a powerful downward hit, usually made by jumping above the net to attack the ball.",tr:"Smaç, genellikle topa saldırmak için filenin üzerine zıplayarak yapılan sert ve aşağı yönlü bir vuruştur."} },
  { id:"spo035", t:"sport", d:2, c:0, en:{q:"In tennis, how many times may the ball bounce on your side before you hit it?",a:["Once","Twice","Three times","It must not bounce"]}, tr:{q:"Teniste vurmadan önce top kendi sahanızda en fazla kaç kez sekebilir?",a:["Bir kez","İki kez","Üç kez","Hiç sekmemeli"]}, ex:{en:"In tennis, the ball may bounce only once on your side before you must return it.",tr:"Teniste top, karşılık vermeden önce kendi sahanızda sadece bir kez sekebilir."} },
  { id:"spo036", t:"sport", d:2, c:0, en:{q:"In athletics, which event is about throwing a heavy metal ball as far as you can?",a:["Shot put","Javelin","Long jump","Hurdles"]}, tr:{q:"Atletizmde ağır metal bir topu olabildiğince uzağa fırlatmak hangi branştır?",a:["Gülle atma","Cirit atma","Uzun atlama","Engelli koşu"]}, ex:{en:"Shot put athletes push a heavy metal ball from the shoulder as far as they can.",tr:"Gülle atma sporcuları, ağır metal bir topu omuzdan olabildiğince uzağa iter."} },
  { id:"spo037", t:"sport", d:2, c:0, en:{q:"Which swimming stroke has the same name as an insect?",a:["Butterfly","Backstroke","Breaststroke","Freestyle"]}, tr:{q:"Hangi yüzme stilinin adı bir böcek adıyla aynıdır?",a:["Kelebek","Sırtüstü","Kurbağalama","Serbest stil"]}, ex:{en:"The butterfly swimming stroke shares its name with the winged insect, thanks to its arm motion.",tr:"Kelebek yüzme stili, kol hareketi nedeniyle kanatlı böcekle aynı adı taşır."} },
  { id:"spo038", t:"sport", d:2, c:0, en:{q:"Which winter sport is done sliding down a snowy mountain on a single wide board?",a:["Snowboarding","Ice skating","Ice hockey","Ski jumping"]}, tr:{q:"Karlı bir dağdan tek bir geniş tahta üzerinde kayarak yapılan kış sporu hangisidir?",a:["Snowboard","Buz pateni","Buz hokeyi","Kayakla atlama"]}, ex:{en:"Snowboarding uses a single wide board strapped to both feet, unlike skiing's two separate skis.",tr:"Snowboardda her iki ayak da tek bir geniş tahtaya bağlanır; kayakta olduğu gibi iki ayrı kayak kullanılmaz."} },
  { id:"spo039", t:"sport", d:2, c:0, en:{q:"In chess, which piece must you protect to avoid losing the game?",a:["The king","The queen","The rook","The pawn"]}, tr:{q:"Satrançta oyunu kaybetmemek için korumanız gereken taş hangisidir?",a:["Şah","Vezir","Kale","Piyon"]}, ex:{en:"Losing your king, called checkmate, ends the game, so it is the piece you must protect above all.",tr:"Şahının alınması, yani şah mat olmak oyunu bitirir; bu yüzden her şeyden önce korunması gereken taştır."} },
  { id:"spo040", t:"sport", d:2, c:0, en:{q:"In a normal pit stop, what does the pit crew change on the car?",a:["The tyres","The seat","The engine","The mirrors"]}, tr:{q:"Normal bir pit stopta ekip aracın neyini değiştirir?",a:["Lastikleri","Koltuğu","Motoru","Aynaları"]}, ex:{en:"A pit stop's main job is fitting a fresh set of tyres to replace ones worn down by the race.",tr:"Pit stopun asıl işi, yarış boyunca aşınan lastiklerin yerine yenilerini takmaktır."} },
  { id:"spo041", t:"sport", d:2, k:"tf", v:true, en:{q:"A football match is played in two halves of 45 minutes each."}, tr:{q:"Bir futbol maçı 45'er dakikalık iki devreden oluşur."}, ex:{en:"A football match runs for two 45-minute halves, with a short break in between.",tr:"Bir futbol maçı, aralarında kısa bir mola olan 45'er dakikalık iki yarıdan oluşur."} },
  { id:"spo042", t:"sport", d:2, k:"tf", v:true, en:{q:"The Summer Olympic Games are held once every four years."}, tr:{q:"Yaz Olimpiyat Oyunları dört yılda bir düzenlenir."}, ex:{en:"The Summer Olympics return every four years, giving athletes time to train between Games.",tr:"Yaz Olimpiyatları her dört yılda bir düzenlenir; bu, sporculara oyunlar arasında antrenman için zaman tanır."} },
  { id:"spo043", t:"sport", d:2, k:"tf", v:false, en:{q:"In badminton, players hit a small rubber ball over the net."}, tr:{q:"Badmintonda oyuncular küçük bir lastik topa vurarak filenin üzerinden geçirir."}, ex:{en:"Badminton is played with a feathered shuttlecock, not a rubber ball, which flies differently through the air.",tr:"Badminton, havada farklı hareket eden lastik bir topla değil, tüylü bir raket topuyla (kozalak) oynanır."} },
  { id:"spo044", t:"sport", d:2, k:"tf", v:false, en:{q:"At the start of a chess game, each player has six pawns."}, tr:{q:"Satranç oyununun başında her oyuncunun altı piyonu vardır."}, ex:{en:"Each chess player starts with eight pawns, one in front of each other piece.",tr:"Her satranç oyuncusu, diğer her taşın önünde birer tane olmak üzere sekiz piyonla başlar."} },
  { id:"spo045", t:"sport", d:2, k:"tf", v:false, en:{q:"In a pool swimming race, swimmers may change lanes whenever they like."}, tr:{q:"Havuzdaki yüzme yarışlarında yüzücüler istedikleri anda kulvar değiştirebilir."}, ex:{en:"Swimmers must stay in their assigned lane for the whole race; leaving it can mean disqualification.",tr:"Yüzücüler yarış boyunca kendilerine ayrılan kulvarda kalmak zorundadır; kulvardan çıkmak diskalifiyeye yol açabilir."} },
  { id:"spo046", t:"sport", d:3, c:0, en:{q:"The Monaco Grand Prix is raced on what kind of track?",a:["Streets of the city","A frozen lake","A sandy desert track","An airport runway"]}, tr:{q:"Monako Grand Prix'si nasıl bir pistte koşulur?",a:["Şehrin sokaklarında","Donmuş bir gölde","Kumlu bir çöl pistinde","Havalimanı pistinde"]}, ex:{en:"The Monaco Grand Prix winds through the narrow public streets of Monte Carlo rather than a purpose-built circuit.",tr:"Monako Grand Prix'si, özel yapılmış bir pist yerine Monte Carlo'nun dar sokaklarında koşulur."} },
  { id:"spo047", t:"sport", d:3, c:0, en:{q:"In football, what must a player do when they are shown a red card?",a:["Leave the pitch","Take a penalty kick","Swap shirts","Stand still for one minute"]}, tr:{q:"Futbolda kırmızı kart gören bir oyuncu ne yapmak zorundadır?",a:["Sahadan çıkmak","Penaltı atmak","Formasını değiştirmek","Bir dakika hareketsiz durmak"]}, ex:{en:"A red card sends a player off for the rest of the match, leaving their team a player short.",tr:"Kırmızı kart, bir oyuncuyu maçın geri kalanında sahadan çıkarır ve takımını bir eksik bırakır."} },
  { id:"spo048", t:"sport", d:3, c:0, en:{q:"The Wimbledon tennis tournament is played on which court surface?",a:["Grass","Clay","Sand","Ice"]}, tr:{q:"Wimbledon tenis turnuvası hangi kort zemininde oynanır?",a:["Çim","Toprak","Kum","Buz"]}, ex:{en:"Wimbledon is the only Grand Slam still played on grass courts, giving the ball a fast, low bounce.",tr:"Wimbledon, hâlâ çim kortlarda oynanan tek Grand Slam turnuvasıdır; bu da topa hızlı ve alçak bir sekme kazandırır."} },
  { id:"spo049", t:"sport", d:3, c:0, en:{q:"How many rings are there on the Olympic flag?",a:["Five","Three","Six","Four"]}, tr:{q:"Olimpiyat bayrağında kaç halka vardır?",a:["Beş","Üç","Altı","Dört"]}, ex:{en:"The Olympic flag's five interlocking rings represent the five inhabited continents joined by the Games.",tr:"Olimpiyat bayrağındaki iç içe geçmiş beş halka, oyunlarla birleşen beş kıtayı temsil eder."} },
  { id:"spo050", t:"sport", d:3, c:0, en:{q:"In basketball, how many points is a successful free throw worth?",a:["One","Two","Three","Five"]}, tr:{q:"Basketbolda başarılı bir serbest atış kaç sayı değerindedir?",a:["Bir","İki","Üç","Beş"]}, ex:{en:"A free throw, taken unopposed from the foul line, is worth one point if it goes in.",tr:"Serbest atış, faul çizgisinden rakipsiz atılır ve girerse bir puan kazandırır."} },
  { id:"spo051", t:"sport", d:3, c:0, en:{q:"About how long is an Olympic marathon race?",a:["About 42 kilometres","About 10 kilometres","About 21 kilometres","About 100 kilometres"]}, tr:{q:"Olimpiyat maratonu yaklaşık kaç kilometredir?",a:["Yaklaşık 42 kilometre","Yaklaşık 10 kilometre","Yaklaşık 21 kilometre","Yaklaşık 100 kilometre"]}, ex:{en:"A marathon covers about 42 kilometres, the distance run in the Olympic road race.",tr:"Maraton, Olimpiyat yol koşusunda kat edilen mesafe olan yaklaşık 42 kilometreyi kapsar."} },
  { id:"spo052", t:"sport", d:3, c:0, en:{q:"In chess, which piece can only move diagonally?",a:["The bishop","The rook","The knight","The pawn"]}, tr:{q:"Satrançta hangi taş yalnızca çapraz hareket eder?",a:["Fil","Kale","At","Piyon"]}, ex:{en:"A bishop stays on squares of one colour for the whole game because it only moves diagonally.",tr:"Fil sadece çapraz hareket ettiği için oyun boyunca hep aynı renk karelerde kalır."} },
  { id:"spo053", t:"sport", d:3, c:0, en:{q:"How many dice does a player roll on their turn in backgammon?",a:["Two","One","Three","Four"]}, tr:{q:"Tavlada bir oyuncu sırası geldiğinde kaç zar atar?",a:["İki","Bir","Üç","Dört"]}, ex:{en:"Backgammon players roll two dice each turn to decide how far their checkers can move.",tr:"Tavla oyuncuları, taşlarının kaç adım gidebileceğini belirlemek için her sırada iki zar atar."} },
  { id:"spo054", t:"sport", d:3, c:0, en:{q:"How many hours does the famous Le Mans car race in France last?",a:["24 hours","12 hours","6 hours","48 hours"]}, tr:{q:"Fransa'daki ünlü Le Mans otomobil yarışı kaç saat sürer?",a:["24 saat","12 saat","6 saat","48 saat"]}, ex:{en:"The Le Mans 24 Hours tests endurance by having teams race non-stop, day and night, for a full day.",tr:"Le Mans 24 Saat yarışı, takımların gece gündüz tam bir gün boyunca durmadan yarışmasıyla dayanıklılığı sınar."} },
  { id:"spo055", t:"sport", d:3, c:0, en:{q:"What colour jersey does the overall leader of the Tour de France wear?",a:["Yellow","Red","Green","Blue"]}, tr:{q:"Fransa Bisiklet Turu'nda genel klasman lideri hangi renk forma giyer?",a:["Sarı","Kırmızı","Yeşil","Mavi"]}, ex:{en:"The rider leading the overall standings in the Tour de France wears the famous yellow jersey.",tr:"Fransa Bisiklet Turu'nda genel klasmanda lider olan bisikletçi ünlü sarı formayı giyer."} },
  { id:"spo056", t:"sport", d:3, c:0, en:{q:"How many players from each team are on court in a volleyball match?",a:["Six","Five","Seven","Eleven"]}, tr:{q:"Voleybol maçında her takımdan sahada kaç oyuncu bulunur?",a:["Altı","Beş","Yedi","On bir"]}, ex:{en:"A volleyball team has six players on court at once, rotating positions after winning serve.",tr:"Bir voleybol takımının sahada aynı anda altı oyuncusu bulunur ve servisi kazandıklarında pozisyon değiştirirler."} },
  { id:"spo057", t:"sport", d:3, c:0, en:{q:"How many pins do you try to knock down in a game of bowling?",a:["Ten","Six","Eight","Twelve"]}, tr:{q:"Bowling oyununda kaç labut devirmeye çalışırsınız?",a:["On","Altı","Sekiz","On iki"]}, ex:{en:"Bowlers aim to knock down all ten pins arranged in a triangle at the end of the lane.",tr:"Bowlingciler, pistin ucunda üçgen şeklinde dizilmiş on lobutun tamamını devirmeyi hedefler."} },
  { id:"spo058", t:"sport", d:3, c:0, en:{q:"In basketball, what is it called when a player takes too many steps without bouncing the ball?",a:["Travelling","A rebound","A slam dunk","An assist"]}, tr:{q:"Basketbolda bir oyuncunun topu sektirmeden fazla adım atmasına ne denir?",a:["Adım hatası","Ribaunt","Smaç","Asist"]}, ex:{en:"Travelling is called when a player carries the ball too many steps without dribbling it.",tr:"Adım hatası, bir oyuncunun topu sektirmeden fazla adım atmasıyla verilir."} },
  { id:"spo059", t:"sport", d:3, c:0, en:{q:"In volleyball, what do we call the defensive player who wears a different coloured shirt?",a:["The libero","The setter","The captain","The coach"]}, tr:{q:"Voleybolda farklı renk forma giyen savunma oyuncusuna ne denir?",a:["Libero","Pasör","Kaptan","Antrenör"]}, ex:{en:"The libero is a defensive specialist who wears a different shirt and cannot serve or attack at the net.",tr:"Libero, farklı forma giyen ve fileden servis ya da hücum yapamayan savunma uzmanı bir oyuncudur."} },
  { id:"spo060", t:"sport", d:3, c:0, en:{q:"In tennis, how many chances does a player get to make a serve on each point?",a:["Two","One","Three","Four"]}, tr:{q:"Teniste bir oyuncunun her sayıda servis atmak için kaç hakkı vardır?",a:["İki","Bir","Üç","Dört"]}, ex:{en:"A player gets a second serve if the first misses, but a second fault loses the point.",tr:"İlk servis kaçarsa oyuncuya ikinci bir hakkı vardır, ama ikinci hata da olursa sayı kaybedilir."} },
  { id:"spo061", t:"sport", d:3, c:0, en:{q:"Which athletics event uses a long bendy pole to get over a high bar?",a:["Pole vault","High jump","Long jump","Triple jump"]}, tr:{q:"Hangi atletizm branşında uzun ve esnek bir sırıkla yüksek çıtanın üzerinden geçilir?",a:["Sırıkla atlama","Yüksek atlama","Uzun atlama","Üç adım atlama"]}, ex:{en:"Pole vaulters use a long flexible pole to launch themselves up and over a high crossbar.",tr:"Sırıkla atlama sporcuları, yüksek bir çıtanın üzerine fırlamak için uzun ve esnek bir sırık kullanır."} },
  { id:"spo062", t:"sport", d:3, c:0, en:{q:"In which swimming stroke do both arms swing forward over the head together?",a:["Butterfly","Breaststroke","Backstroke","Freestyle"]}, tr:{q:"Hangi yüzme stilinde iki kol birlikte başın üzerinden öne savrulur?",a:["Kelebek","Kurbağalama","Sırtüstü","Serbest stil"]}, ex:{en:"In butterfly, both arms pull through the water together and swing forward over the head in unison.",tr:"Kelebek stilinde her iki kol da birlikte suda çekiş yapar ve eş zamanlı olarak başın üzerinden öne savrulur."} },
  { id:"spo063", t:"sport", d:3, c:0, en:{q:"In which winter sport do players slide heavy stones across the ice towards a target?",a:["Curling","Ice hockey","Bobsleigh","Ski jumping"]}, tr:{q:"Hangi kış sporunda ağır taşlar buz üzerinde bir hedefe doğru kaydırılır?",a:["Curling","Buz hokeyi","Bobsleigh","Kayakla atlama"]}, ex:{en:"Curling players slide heavy granite stones down the ice, aiming for a circular target called the house.",tr:"Curling oyuncuları, ev denilen dairesel bir hedefe doğru ağır granit taşları buzda kaydırır."} },
  { id:"spo064", t:"sport", d:3, c:0, en:{q:"In Turkey's traditional sport of oil wrestling, which oil do the wrestlers use?",a:["Olive oil","Sunflower oil","Coconut oil","Fish oil"]}, tr:{q:"Türkiye'nin geleneksel sporu yağlı güreşte pehlivanlar hangi yağı kullanır?",a:["Zeytinyağı","Ayçiçek yağı","Hindistan cevizi yağı","Balık yağı"]}, ex:{en:"Turkish oil wrestlers, called pehlivan, coat their skin in olive oil before every bout.",tr:"Pehlivan adı verilen Türk yağlı güreşçileri, her maçtan önce derilerini zeytinyağıyla kaplar."} },
  { id:"spo065", t:"sport", d:3, c:0, en:{q:"How many squares are there in total on a chessboard?",a:["64","32","81","100"]}, tr:{q:"Bir satranç tahtasında toplam kaç kare vardır?",a:["64","32","81","100"]}, ex:{en:"A chessboard has 64 squares arranged in an 8 by 8 grid.",tr:"Bir satranç tahtası, 8'e 8'lik bir düzende yerleşmiş 64 kareden oluşur."} },
  { id:"spo066", t:"sport", d:3, k:"tf", v:true, en:{q:"Basketball was invented by a gym teacher who hung up two peach baskets as the first hoops."}, tr:{q:"Basketbolu, ilk pota olarak iki şeftali sepeti asan bir beden eğitimi öğretmeni icat etti."}, ex:{en:"James Naismith invented basketball in 1891, nailing up two peach baskets to serve as the first goals.",tr:"James Naismith, 1891'de ilk potalar olarak iki şeftali sepeti çakarak basketbolu icat etti."} },
  { id:"spo067", t:"sport", d:3, k:"tf", v:false, en:{q:"In tennis, the serve must land in the service box directly across from the server."}, tr:{q:"Teniste servis atışı, oyuncunun tam karşısındaki servis karesine düşmek zorundadır."}, ex:{en:"A serve must land in the service box diagonally opposite the server, not the one directly across.",tr:"Servis, sunucunun tam karşısındaki değil, çapraz karşısındaki servis kutusuna düşmelidir."} },
  { id:"spo068", t:"sport", d:3, k:"tf", v:false, en:{q:"One full lap of a standard outdoor running track is 500 metres."}, tr:{q:"Standart bir açık hava koşu pistinin bir tam turu 500 metredir."}, ex:{en:"A standard outdoor athletics track measures 400 metres for one full lap, not 500.",tr:"Standart bir dış mekân atletizm pisti bir tam tur için 500 değil, 400 metredir."} },
  { id:"spo069", t:"sport", d:3, k:"tf", v:true, en:{q:"In a freestyle swimming race, swimmers are allowed to use any stroke they want."}, tr:{q:"Serbest stil yüzme yarışında yüzücüler istedikleri her stili kullanabilir."}, ex:{en:"\"Freestyle\" simply means any stroke is allowed, which is why swimmers almost always choose front crawl for speed.",tr:"\"Serbest stil\", herhangi bir stile izin verildiği anlamına gelir; bu yüzden yüzücüler hız için neredeyse hep krolü seçer."} },
  { id:"spo070", t:"sport", d:4, c:0, en:{q:"What does 'pole position' mean in Formula 1?",a:["Starting the race in first place","Winning the race","Being last on the starting grid","Setting the fastest lap of the race"]}, tr:{q:"Formula 1'de 'pole pozisyonu' ne demektir?",a:["Yarışa ilk sırada başlamak","Yarışı kazanmak","Başlangıç sıralamasında sonuncu olmak","Yarışın en hızlı turunu atmak"]}, ex:{en:"Pole position is the front spot on the starting grid, earned by setting the fastest lap in qualifying.",tr:"Pole pozisyonu, sıralama turlarında en hızlı turu atarak kazanılan, gridin en öndeki yeridir."} },
  { id:"spo071", t:"sport", d:4, c:0, en:{q:"In football, what is it called when one player scores three goals in a match?",a:["A hat-trick","An assist","A free kick","A penalty"]}, tr:{q:"Futbolda bir oyuncunun aynı maçta üç gol atmasına ne denir?",a:["Hat-trick","Asist","Frikik","Penaltı"]}, ex:{en:"Scoring three goals in one match earns a player the nickname hat-trick, from an old cricket tradition.",tr:"Bir maçta üç gol atmak, eski bir kriket geleneğinden gelen hat-trick lakabını kazandırır."} },
  { id:"spo072", t:"sport", d:4, c:0, en:{q:"Which of the four tennis Grand Slam tournaments is played on grass courts?",a:["Wimbledon","The French Open","The US Open","The Australian Open"]}, tr:{q:"Tenisin dört Grand Slam turnuvasından hangisi çim kortta oynanır?",a:["Wimbledon","Fransa Açık","ABD Açık","Avustralya Açık"]}, ex:{en:"Wimbledon is the only one of the four Grand Slams played on grass, giving matches a distinct fast style.",tr:"Wimbledon, dört Grand Slam'den çim üzerinde oynanan tek turnuvadır ve maçlara kendine özgü hızlı bir tarz katar."} },
  { id:"spo073", t:"sport", d:4, c:0, en:{q:"How many players from each team are on the court during a basketball match?",a:["Five","Six","Seven","Four"]}, tr:{q:"Bir basketbol maçında her takımdan sahada kaç oyuncu bulunur?",a:["Beş","Altı","Yedi","Dört"]}, ex:{en:"Basketball is played five against five, with each team fielding five players on court at once.",tr:"Basketbol beşe beş oynanır; her takımın sahada aynı anda beş oyuncusu bulunur."} },
  { id:"spo074", t:"sport", d:4, c:0, en:{q:"How long is an official marathon race?",a:["42.195 km","21.095 km","50 km","32 km"]}, tr:{q:"Resmî bir maraton koşusunun uzunluğu ne kadardır?",a:["42,195 km","21,095 km","50 km","32 km"]}, ex:{en:"The official marathon distance, 42.195 km, dates back to the 1908 London Olympics course.",tr:"Resmi maraton mesafesi olan 42,195 km, 1908 Londra Olimpiyatları parkuruna kadar uzanır."} },
  { id:"spo075", t:"sport", d:4, c:0, en:{q:"In which swimming stroke do racers start in the water instead of diving in?",a:["Backstroke","Butterfly","Breaststroke","Freestyle"]}, tr:{q:"Hangi yüzme stilinde yarışmacılar atlayarak değil, suyun içinde başlar?",a:["Sırtüstü","Kelebek","Kurbağalama","Serbest stil"]}, ex:{en:"Backstroke races start with swimmers already in the water, gripping the wall, instead of diving off blocks.",tr:"Sırtüstü yarışlarda yüzücüler bloklardan dalış yapmak yerine suyun içinde duvara tutunarak başlar."} },
  { id:"spo076", t:"sport", d:4, c:0, en:{q:"In volleyball, how many touches may a team make before the ball must go over the net?",a:["Three","Two","Four","Five"]}, tr:{q:"Voleybolda bir takım, top fileyi geçmeden önce en fazla kaç kez dokunabilir?",a:["Üç","İki","Dört","Beş"]}, ex:{en:"A team may touch the ball up to three times before sending it back over the net.",tr:"Bir takım, topu tekrar fileden geçirmeden önce en fazla üç kez ona dokunabilir."} },
  { id:"spo077", t:"sport", d:4, c:0, en:{q:"In chess, which piece can jump over other pieces?",a:["The knight","The bishop","The rook","The queen"]}, tr:{q:"Satrançta hangi taş diğer taşların üzerinden atlayabilir?",a:["At","Fil","Kale","Vezir"]}, ex:{en:"The knight moves in an L-shape and is the only piece that can leap over others on the board.",tr:"At, L şeklinde hareket eder ve tahtadaki diğer taşların üzerinden atlayabilen tek taştır."} },
  { id:"spo078", t:"sport", d:4, c:0, en:{q:"In rally racing, what is the person who sits beside the driver reading the notes called?",a:["The co-driver","The mechanic","The team manager","The marshal"]}, tr:{q:"Ralli yarışlarında sürücünün yanında oturup yol notlarını okuyan kişiye ne denir?",a:["Ko-pilot","Tamirci","Takım menajeri","Pist görevlisi"]}, ex:{en:"A rally co-driver reads pace notes aloud, warning the driver about upcoming corners at high speed.",tr:"Ralli yardımcı pilotu, yüksek hızda ilerleyen sürücüyü yaklaşan virajlara karşı uyaran pace notlarını sesli okur."} },
  { id:"spo079", t:"sport", d:4, c:0, en:{q:"In which city were the first modern Olympic Games held in 1896?",a:["Athens","Paris","London","Rome"]}, tr:{q:"İlk modern Olimpiyat Oyunları 1896'da hangi şehirde düzenlendi?",a:["Atina","Paris","Londra","Roma"]}, ex:{en:"The first modern Olympic Games were held in Athens in 1896, reviving the ancient Greek tradition.",tr:"İlk modern Olimpiyat Oyunları, antik Yunan geleneğini canlandırarak 1896'da Atina'da düzenlendi."} },
  { id:"spo080", t:"sport", d:4, c:0, en:{q:"Naim Süleymanoğlu, nicknamed \"Pocket Hercules\", was an Olympic champion in which sport?",a:["Weightlifting","Wrestling","Boxing","Athletics"]}, tr:{q:"\"Cep Herkülü\" lakaplı Naim Süleymanoğlu hangi sporun olimpiyat şampiyonuydu?",a:["Halter","Güreş","Boks","Atletizm"]}, ex:{en:"Naim Süleymanoğlu won Olympic weightlifting gold for Türkiye three times despite his small frame.",tr:"Naim Süleymanoğlu, ufak yapısına rağmen Türkiye için üç kez Olimpiyat halter altını kazandı."} },
  { id:"spo081", t:"sport", d:4, c:0, en:{q:"Which two countries hosted the 2002 FIFA World Cup together?",a:["South Korea and Japan","Germany and Austria","Brazil and Argentina","Spain and Portugal"]}, tr:{q:"2002 FIFA Dünya Kupası'na hangi iki ülke birlikte ev sahipliği yaptı?",a:["Güney Kore ve Japonya","Almanya ve Avusturya","Brezilya ve Arjantin","İspanya ve Portekiz"]}, ex:{en:"The 2002 World Cup was jointly hosted by South Korea and Japan, the first tournament shared by two countries.",tr:"2002 Dünya Kupası'na Güney Kore ve Japonya birlikte ev sahipliği yaptı; bu, iki ülke tarafından paylaşılan ilk turnuvaydı."} },
  { id:"spo082", t:"sport", d:4, c:0, en:{q:"In tennis, what is the score called when both players reach 40?",a:["Deuce","Love","Advantage","Match point"]}, tr:{q:"Teniste iki oyuncu da 40 sayıya ulaştığında bu skora ne denir?",a:["Deuce","Love","Avantaj","Maç sayısı"]}, ex:{en:"When both players reach 40, the score is called deuce, and one player must then lead by two points to win.",tr:"İki oyuncu da 40'a ulaştığında skora deuce (eşitlik) denir ve kazanmak için birinin iki sayı öne geçmesi gerekir."} },
  { id:"spo083", t:"sport", d:4, c:0, en:{q:"How many hurdles does a runner clear in a 110 metres hurdles race?",a:["Ten","Eight","Twelve","Six"]}, tr:{q:"110 metre engelli koşuda bir atlet kaç engel aşar?",a:["On","Sekiz","On iki","Altı"]}, ex:{en:"A 110 metres hurdles runner clears exactly ten evenly spaced hurdles along the track.",tr:"110 metre engelli koşucusu, pist boyunca eşit aralıklarla dizilmiş tam on engelin üzerinden geçer."} },
  { id:"spo084", t:"sport", d:4, c:0, en:{q:"In competitive swimming, which of the four strokes is the fastest?",a:["Freestyle (front crawl)","Butterfly","Backstroke","Breaststroke"]}, tr:{q:"Yüzme yarışlarında dört stilden hangisi en hızlısıdır?",a:["Serbest (kroul)","Kelebek","Sırtüstü","Kurbağalama"]}, ex:{en:"Freestyle, usually swum as front crawl, is the fastest of the four competitive strokes.",tr:"Genellikle krol olarak yüzülen serbest stil, dört yarışma stilinin en hızlısıdır."} },
  { id:"spo085", t:"sport", d:4, c:0, en:{q:"In cycling races, what is the 'peloton'?",a:["The main group of riders","The finish line","A kind of bicycle","A mountain stage"]}, tr:{q:"Bisiklet yarışlarında 'peloton' nedir?",a:["Yarışçıların ana grubu","Bitiş çizgisi","Bir bisiklet türü","Bir dağ etabı"]}, ex:{en:"The peloton is the large main pack of riders, who save energy by cycling close together.",tr:"Peloton, birbirine yakın giderek enerji tasarrufu yapan büyük ana bisikletçi grubudur."} },
  { id:"spo086", t:"sport", d:4, c:0, en:{q:"Turkey's famous Kırkpınar festival in Edirne is a competition in which sport?",a:["Oil wrestling","Archery","Weightlifting","Horse racing"]}, tr:{q:"Edirne'deki ünlü Kırkpınar festivali hangi sporun müsabakasıdır?",a:["Yağlı güreş","Okçuluk","Halter","At yarışı"]}, ex:{en:"Kırkpınar, held in Edirne since the 1300s, is the world's oldest continuously running oil wrestling festival.",tr:"1300'lerden beri Edirne'de düzenlenen Kırkpınar, dünyanın kesintisiz süren en eski yağlı güreş festivalidir."} },
  { id:"spo087", t:"sport", d:4, c:0, en:{q:"Which Winter Olympic sport combines cross-country skiing with target shooting?",a:["Biathlon","Curling","Bobsleigh","Ski jumping"]}, tr:{q:"Hangi Kış Olimpiyatları sporu kayaklı koşu ile atıcılığı birleştirir?",a:["Biatlon","Curling","Bobsleigh","Kayakla atlama"]}, ex:{en:"Biathlon combines endurance skiing with the precision of stopping to shoot at targets.",tr:"Biatlon, dayanıklılık gerektiren kayağı, durup hedefleri vurmanın hassasiyetiyle birleştirir."} },
  { id:"spo088", t:"sport", d:4, c:0, en:{q:"The Silverstone circuit is in which country?",a:["The United Kingdom","Germany","Spain","Belgium"]}, tr:{q:"Silverstone pisti hangi ülkededir?",a:["Birleşik Krallık","Almanya","İspanya","Belçika"]}, ex:{en:"Silverstone, home of the British Grand Prix, is located in Northamptonshire, England.",tr:"İngiltere Grand Prix'sine ev sahipliği yapan Silverstone, İngiltere'nin Northamptonshire bölgesindedir."} },
  { id:"spo089", t:"sport", d:4, k:"tf", v:true, en:{q:"In football, the penalty spot is 11 metres from the goal line."}, tr:{q:"Futbolda penaltı noktası kale çizgisine 11 metre uzaklıktadır."}, ex:{en:"The penalty spot sits exactly 11 metres, or 12 yards, from the goal line.",tr:"Penaltı noktası, kale çizgisinden tam olarak 11 metre (12 yarda) uzaklıktadır."} },
  { id:"spo090", t:"sport", d:4, k:"tf", v:true, en:{q:"In international basketball under FIBA rules, a game is made up of four ten-minute quarters."}, tr:{q:"FIBA kurallarıyla oynanan uluslararası basketbolda bir maç 10'ar dakikalık dört çeyrekten oluşur."}, ex:{en:"FIBA, the international basketball body, splits games into four quarters of ten minutes each.",tr:"Uluslararası basketbol kurumu FIBA, maçları dörder onar dakikalık dört periyoda ayırır."} },
  { id:"spo091", t:"sport", d:4, k:"tf", v:false, en:{q:"Usain Bolt won his Olympic sprint gold medals running for Trinidad and Tobago."}, tr:{q:"Usain Bolt, olimpiyat sprint altın madalyalarını Trinidad ve Tobago adına kazandı."}, ex:{en:"Usain Bolt won all his Olympic sprint titles representing Jamaica, not Trinidad and Tobago.",tr:"Usain Bolt, tüm Olimpiyat sprint şampiyonluklarını Trinidad ve Tobago değil, Jamaika adına kazandı."} },
  { id:"spo092", t:"sport", d:4, k:"tf", v:false, en:{q:"The four tennis Grand Slams are the Australian Open, the French Open, Wimbledon and the Canadian Open."}, tr:{q:"Tenisin dört Grand Slam turnuvası Avustralya Açık, Fransa Açık, Wimbledon ve Kanada Açık'tır."}, ex:{en:"The fourth Grand Slam is the US Open, not the Canadian Open, alongside the Australian Open, French Open and Wimbledon.",tr:"Dördüncü Grand Slam, Kanada Açık değil, Amerika Açık'tır; diğerleri Avustralya Açık, Fransa Açık ve Wimbledon'dır."} },
  { id:"spo093", t:"sport", d:4, k:"tf", v:false, en:{q:"The Winter Olympics are held in the same year as the Summer Olympics."}, tr:{q:"Kış Olimpiyatları, Yaz Olimpiyatları ile aynı yıl düzenlenir."}, ex:{en:"Since 1994 the Winter and Summer Games have alternated, landing two years apart rather than the same year.",tr:"1994'ten beri Kış ve Yaz Oyunları birbirini izler ve aynı yılda değil, iki yıl arayla düzenlenir."} },
  { id:"spo094", t:"sport", d:5, c:0, en:{q:"How many points does the winner of a Grand Prix score?",a:["25","10","50","20"]}, tr:{q:"Bir Grand Prix'yi kazanan pilot kaç puan alır?",a:["25","10","50","20"]}, ex:{en:"Under the current points system, a Grand Prix winner earns 25 championship points.",tr:"Güncel puan sistemine göre bir Grand Prix'yi kazanan pilot 25 şampiyona puanı kazanır."} },
  { id:"spo095", t:"sport", d:5, c:0, en:{q:"Which Formula 1 team is based in Maranello, Italy?",a:["Ferrari","McLaren","Williams","Renault"]}, tr:{q:"İtalya'nın Maranello kasabasında hangi Formula 1 takımının merkezi vardır?",a:["Ferrari","McLaren","Williams","Renault"]}, ex:{en:"Ferrari's factory and headquarters are based in Maranello, in northern Italy.",tr:"Ferrari'nin fabrikası ve genel merkezi, Kuzey İtalya'daki Maranello'da bulunur."} },
  { id:"spo096", t:"sport", d:5, c:0, en:{q:"Which country won the first FIFA World Cup, held in 1930?",a:["Uruguay","Brazil","Argentina","Italy"]}, tr:{q:"1930'da düzenlenen ilk FIFA Dünya Kupası'nı hangi ülke kazandı?",a:["Uruguay","Brezilya","Arjantin","İtalya"]}, ex:{en:"Uruguay hosted and won the very first FIFA World Cup, held in Montevideo in 1930.",tr:"Uruguay, 1930'da Montevideo'da düzenlenen ilk FIFA Dünya Kupası'na hem ev sahipliği yaptı hem de kazandı."} },
  { id:"spo097", t:"sport", d:5, c:0, en:{q:"In basketball, how many seconds does a team have to attempt a shot?",a:["24 seconds","30 seconds","45 seconds","12 seconds"]}, tr:{q:"Basketbolda bir takımın şut atmak için kaç saniyesi vardır?",a:["24 saniye","30 saniye","45 saniye","12 saniye"]}, ex:{en:"A team in basketball must attempt a shot within 24 seconds of gaining possession, or lose the ball.",tr:"Basketbolda bir takım, topa sahip olduktan sonra 24 saniye içinde şut denemek zorundadır, yoksa topu kaybeder."} },
  { id:"spo098", t:"sport", d:5, c:0, en:{q:"In chess, which move lets the king and a rook move on the same turn?",a:["Castling","En passant","Promotion","Check"]}, tr:{q:"Satrançta şah ile kalenin aynı hamlede oynandığı hamle hangisidir?",a:["Rok","Geçerken alma","Piyon terfisi","Şah çekme"]}, ex:{en:"Castling lets the king slide two squares towards a rook, which then hops to the other side, all in one move.",tr:"Rok, şahın bir kaleye doğru iki kare kaymasını ve kalenin de tek bir hamlede diğer tarafa atlamasını sağlar."} },
  { id:"spo099", t:"sport", d:5, c:0, en:{q:"In backgammon, how many checkers does each player start with?",a:["15","12","10","20"]}, tr:{q:"Tavlada her oyuncu kaç pulla başlar?",a:["15","12","10","20"]}, ex:{en:"Each backgammon player starts with 15 checkers, arranged across the board in a set pattern.",tr:"Her tavla oyuncusu, tahta üzerinde belirli bir düzende dizilmiş 15 taşla oyuna başlar."} },
  { id:"spo100", t:"sport", d:5, c:0, en:{q:"How long is an Olympic-size swimming pool?",a:["50 metres","25 metres","100 metres","75 metres"]}, tr:{q:"Olimpik yüzme havuzu kaç metre uzunluğundadır?",a:["50 metre","25 metre","100 metre","75 metre"]}, ex:{en:"An Olympic-size pool measures exactly 50 metres from end to end.",tr:"Olimpik büyüklükteki bir havuz, bir uçtan diğerine tam olarak 50 metredir."} },
  { id:"spo101", t:"sport", d:5, c:0, en:{q:"In volleyball, how many points does a team need to win a normal set?",a:["25","21","15","30"]}, tr:{q:"Voleybolda bir takım normal bir seti kaç sayıda kazanır?",a:["25","21","15","30"]}, ex:{en:"A volleyball set is won by reaching 25 points first, provided the lead is at least two points.",tr:"Bir voleybol seti, en az iki sayı farkla ilk 25'e ulaşan tarafından kazanılır."} },
  { id:"spo102", t:"sport", d:5, c:0, en:{q:"In golf, what is a score of one stroke under par on a hole called?",a:["A birdie","An eagle","A bogey","An albatross"]}, tr:{q:"Golfte bir delikte pardan bir vuruş az atmaya ne denir?",a:["Birdie","Eagle","Bogey","Albatros"]}, ex:{en:"A birdie means finishing a hole in one stroke fewer than its par score.",tr:"Birdie, bir çukuru parından bir vuruş daha az yaparak bitirmek demektir."} },
  { id:"spo103", t:"sport", d:5, c:0, en:{q:"How many dots are there in total on a standard six-sided dice?",a:["21","18","24","20"]}, tr:{q:"Standart altı yüzlü bir zarın üzerinde toplam kaç nokta vardır?",a:["21","18","24","20"]}, ex:{en:"The numbers 1 through 6 on a die add up to 21 in total.",tr:"Bir zar üzerindeki 1'den 6'ya kadar sayıların toplamı 21'dir."} },
  { id:"spo104", t:"sport", d:5, c:0, en:{q:"In football, what is the fewest players a team can have on the pitch and keep playing?",a:["Seven","Six","Eight","Nine"]}, tr:{q:"Futbolda bir takım sahada en az kaç oyuncuyla maça devam edebilir?",a:["Yedi","Altı","Sekiz","Dokuz"]}, ex:{en:"A football team can continue with as few as seven players; fewer than that ends the match.",tr:"Bir futbol takımı en az yedi oyuncuyla devam edebilir; bundan azıysa maç sona erer."} },
  { id:"spo105", t:"sport", d:5, c:0, en:{q:"How high above the floor is the basketball ring in official games?",a:["3.05 m","2.75 m","3.50 m","4.00 m"]}, tr:{q:"Resmî basketbol maçlarında pota çemberi yerden kaç metre yüksektedir?",a:["3,05 m","2,75 m","3,50 m","4,00 m"]}, ex:{en:"Basketball hoops are fixed at exactly 3.05 metres, or 10 feet, above the floor in official games.",tr:"Resmi maçlarda basketbol potaları yerden tam olarak 3,05 metre (10 fit) yükseklikte sabitlenir."} },
  { id:"spo106", t:"sport", d:5, c:0, en:{q:"In tennis, how many points in a row must a player win to take a game from 0-0?",a:["Four","Three","Five","Six"]}, tr:{q:"Teniste 0-0'dan başlayarak bir oyunu kazanmak için üst üste kaç sayı almak gerekir?",a:["Dört","Üç","Beş","Altı"]}, ex:{en:"A player must win four points before their opponent to take a game, unless the score reaches deuce.",tr:"Bir oyuncunun oyunu alması için skor deuce'e gitmediği sürece rakibinden önce dört sayı kazanması gerekir."} },
  { id:"spo107", t:"sport", d:5, c:0, en:{q:"In artistic gymnastics, which apparatus is used only by male gymnasts?",a:["The pommel horse","The balance beam","The uneven bars","The floor"]}, tr:{q:"Artistik jimnastikte hangi alet yalnızca erkek sporcular tarafından kullanılır?",a:["Kulplu beygir","Denge aleti","Asimetrik paralel","Yer minderi"]}, ex:{en:"The pommel horse, requiring circular swinging movements, appears only in men's artistic gymnastics.",tr:"Dairesel sallanma hareketleri gerektiren kulplu beygir, yalnızca erkekler artistik jimnastiğinde yer alır."} },
  { id:"spo108", t:"sport", d:5, c:0, en:{q:"In Greco-Roman wrestling, what are the wrestlers forbidden to do?",a:["Hold below the waist","Hold the opponent's arms","Lift the opponent off the mat","Win by pinning the shoulders"]}, tr:{q:"Grekoromen güreşte sporcuların yapması yasak olan hareket hangisidir?",a:["Belden aşağısını tutmak","Rakibin kollarını tutmak","Rakibi yerden kaldırmak","Tuşla kazanmak"]}, ex:{en:"Greco-Roman wrestling bans holds and attacks below the waist, focusing all action on the upper body.",tr:"Grekoromen güreşte belden aşağı tutuş ve saldırılar yasaktır, tüm mücadele üst beden üzerinden yürütülür."} },
  { id:"spo109", t:"sport", d:5, c:0, en:{q:"In cycling, what is the oval track with steeply banked sides called?",a:["A velodrome","A hippodrome","A peloton","A criterium"]}, tr:{q:"Bisiklette kenarları dik eğimli oval pistin adı nedir?",a:["Velodrom","Hipodrom","Peloton","Kriteryum"]}, ex:{en:"A velodrome's steeply banked oval track lets cyclists race at high speed without sliding off the curves.",tr:"Velodromun dik eğimli oval pisti, bisikletçilerin virajlardan kaymadan yüksek hızda yarışmasını sağlar."} },
  { id:"spo110", t:"sport", d:5, k:"tf", v:true, en:{q:"A volleyball set is won by the first team to reach 25 points with a two-point lead."}, tr:{q:"Voleybolda bir set, iki sayı farkla 25'e ulaşan takımın olur."}, ex:{en:"A volleyball set finishes at 25 points, but only once the winning side is also two points clear.",tr:"Bir voleybol seti 25 sayıda biter, ama bu ancak kazanan tarafın iki sayı farkı da tutturmasıyla gerçekleşir."} },
  { id:"spo111", t:"sport", d:5, k:"tf", v:true, en:{q:"In football, a goalkeeper may not pick up the ball that a team-mate has deliberately kicked to them."}, tr:{q:"Futbolda kaleci, takım arkadaşının bilerek ayağıyla kendisine gönderdiği topu eline alamaz."}, ex:{en:"The back-pass rule stops goalkeepers handling the ball after a deliberate kick from their own team-mate.",tr:"Geri pas kuralı, kalecinin kendi takım arkadaşının kasıtlı ayak pasından sonra topu elle tutmasını engeller."} },
  { id:"spo112", t:"sport", d:5, k:"tf", v:false, en:{q:"An NBA basketball game is played in four quarters of ten minutes each."}, tr:{q:"NBA'de bir basketbol maçı onar dakikalık dört çeyrek hâlinde oynanır."}, ex:{en:"NBA quarters last 12 minutes each; the shorter 10-minute quarter belongs to international FIBA rules.",tr:"NBA periyotları 12'şer dakikadır; 10 dakikalık daha kısa periyot uluslararası FIBA kurallarına aittir."} },
  { id:"spo113", t:"sport", d:5, k:"tf", v:false, en:{q:"In tennis, a serve that touches the net and still lands in the correct service box counts as a fault."}, tr:{q:"Teniste, fileye değdiği hâlde doğru servis alanına düşen servis hata sayılır."}, ex:{en:"A serve that clips the net and still lands in the correct box is a let, replayed rather than counted as a fault.",tr:"File'ye değip doğru kutuya düşen bir servis let sayılır ve hata olarak değil, yeniden oynanarak değerlendirilir."} },
  { id:"spo114", t:"sport", d:5, k:"tf", v:true, en:{q:"Races on an athletics track are run in an anticlockwise direction."}, tr:{q:"Atletizm pistindeki koşular saat yönünün tersine yapılır."}, ex:{en:"Track races have run anticlockwise by international convention since the modern rules were set.",tr:"Pist yarışları, modern kurallar belirlendiğinden beri uluslararası gelenek gereği saat yönünün tersine koşulur."} },
  { id:"spo115", t:"sport", d:6, c:0, en:{q:"Which German driver won seven world titles, five of them with Ferrari?",a:["Michael Schumacher","Sebastian Vettel","Nico Rosberg","Ralf Schumacher"]}, tr:{q:"Beşi Ferrari ile olmak üzere yedi dünya şampiyonluğu kazanan Alman pilot kimdir?",a:["Michael Schumacher","Sebastian Vettel","Nico Rosberg","Ralf Schumacher"]} },
  { id:"spo116", t:"sport", d:6, c:0, en:{q:"In tennis, a tie-break is normally played when the games in a set reach what score?",a:["6-6","5-5","7-7","4-4"]}, tr:{q:"Teniste bir sette oyunlar hangi skora ulaştığında normalde tie-break oynanır?",a:["6-6","5-5","7-7","4-4"]} },
  { id:"spo117", t:"sport", d:6, c:0, en:{q:"In chess, what is it called when a player has no legal move but is not in check?",a:["Stalemate","Checkmate","Castling","En passant"]}, tr:{q:"Satrançta, şahı tehdit altında olmayan bir oyuncunun hiç geçerli hamlesi kalmamasına ne denir?",a:["Pat","Şah mat","Rok","Geçerken alma"]} },
  { id:"spo118", t:"sport", d:6, c:0, en:{q:"In Monopoly, what happens if you roll doubles three times in a row?",a:["You go to jail","You collect money from the bank","You get a free property","You move back three spaces"]}, tr:{q:"Monopoly'de üst üste üç kez çift atarsan ne olur?",a:["Hapse girersin","Bankadan para alırsın","Bedava bir mülk alırsın","Üç kare geri gidersin"]} },
  { id:"spo119", t:"sport", d:6, c:0, en:{q:"In the Tour de France, what does the polka-dot jersey mark?",a:["The best climber","The fastest sprinter","The best young rider","The overall leader"]}, tr:{q:"Fransa Bisiklet Turu'nda puantiyeli forma neyi simgeler?",a:["En iyi tırmanıcıyı","En hızlı sprinteri","En iyi genç yarışçıyı","Genel klasman liderini"]} },
  { id:"spo120", t:"sport", d:6, c:0, en:{q:"Turkey finished third at the 2002 World Cup by beating which team in the play-off?",a:["South Korea","Japan","Brazil","Germany"]}, tr:{q:"Türkiye 2002 Dünya Kupası'nda üçüncülük maçında hangi takımı yenerek üçüncü oldu?",a:["Güney Kore","Japonya","Brezilya","Almanya"]} },
  { id:"spo121", t:"sport", d:6, c:0, en:{q:"In tennis, what is it called when a player wins a game on the opponent's serve?",a:["A break of serve","An ace","A let","A smash"]}, tr:{q:"Teniste bir oyuncunun rakibinin servisinde oyunu kazanmasına ne denir?",a:["Servis kırma (break)","As servis","Let","Smaç"]} },
  { id:"spo122", t:"sport", d:6, c:0, en:{q:"In the 1500 m freestyle, how many lengths of a 50 m pool does the swimmer cover?",a:["30 lengths","15 lengths","60 lengths","20 lengths"]}, tr:{q:"1500 metre serbest stilde yüzücü 50 metrelik havuzu kaç kez baştan sona geçer?",a:["30 kez","15 kez","60 kez","20 kez"]} },
  { id:"spo123", t:"sport", d:6, c:0, en:{q:"Which British driver won his first Formula 1 world title in 2008?",a:["Lewis Hamilton","Jenson Button","Nigel Mansell","David Coulthard"]}, tr:{q:"İlk Formula 1 dünya şampiyonluğunu 2008'de kazanan İngiliz pilot kimdir?",a:["Lewis Hamilton","Jenson Button","Nigel Mansell","David Coulthard"]} },
  { id:"spo124", t:"sport", d:6, c:0, en:{q:"The Spa-Francorchamps circuit hosts the Grand Prix of which country?",a:["Belgium","The Netherlands","France","Germany"]}, tr:{q:"Spa-Francorchamps pisti hangi ülkenin Grand Prix'sine ev sahipliği yapar?",a:["Belçika","Hollanda","Fransa","Almanya"]} },
  { id:"spo125", t:"sport", d:6, c:0, en:{q:"Mercedes, Red Bull and McLaren all have their F1 factories in which country?",a:["The United Kingdom","Germany","Austria","Italy"]}, tr:{q:"Mercedes, Red Bull ve McLaren'ın F1 fabrikaları hangi ülkededir?",a:["Birleşik Krallık","Almanya","Avusturya","İtalya"]} },
  { id:"spo126", t:"sport", d:6, k:"tf", v:true, en:{q:"In football, offside is not called on a ball received directly from a throw-in."}, tr:{q:"Futbolda, taç atışından doğrudan gelen topta ofsayt verilmez."} },
  { id:"spo127", t:"sport", d:6, k:"tf", v:false, en:{q:"Germany is the only country to have taken part in every FIFA World Cup."}, tr:{q:"Almanya, bugüne kadar her FIFA Dünya Kupası'na katılmış tek ülkedir."} },
  { id:"spo128", t:"sport", d:6, k:"tf", v:false, en:{q:"In the tennis season, Wimbledon is played before the French Open each year."}, tr:{q:"Tenis sezonunda Wimbledon her yıl Fransa Açık'tan önce oynanır."} },
  { id:"spo129", t:"sport", d:6, k:"tf", v:true, en:{q:"In the high jump, an athlete is out of the competition after three failed attempts in a row."}, tr:{q:"Yüksek atlamada bir sporcu üst üste üç başarısız denemeden sonra yarışmadan elenir."} },
  { id:"spo130", t:"sport", d:6, k:"tf", v:true, en:{q:"Michael Phelps won eight gold medals at the 2008 Beijing Olympics."}, tr:{q:"Michael Phelps 2008 Pekin Olimpiyatları'nda sekiz altın madalya kazandı."} },
  { id:"spo131", t:"sport", d:7, c:0, en:{q:"What does DRS stand for in Formula 1?",a:["Drag Reduction System","Direct Racing Setup","Dynamic Rear Suspension","Driver Response System"]}, tr:{q:"Formula 1'de DRS neyin kısaltmasıdır?",a:["Drag Reduction System","Direct Racing Setup","Dynamic Rear Suspension","Driver Response System"]} },
  { id:"spo132", t:"sport", d:7, c:0, en:{q:"The famous corner Eau Rouge is part of which Grand Prix circuit?",a:["Spa-Francorchamps","Monza","Silverstone","Suzuka"]}, tr:{q:"Ünlü Eau Rouge virajı hangi Grand Prix pistinde bulunur?",a:["Spa-Francorchamps","Monza","Silverstone","Suzuka"]} },
  { id:"spo133", t:"sport", d:7, c:0, en:{q:"In football, what is the radius of the centre circle on a full-size pitch?",a:["9.15 m","7.32 m","11 m","5.5 m"]}, tr:{q:"Futbolda tam ölçülü bir sahada orta yuvarlağın yarıçapı kaçtır?",a:["9,15 m","7,32 m","11 m","5,5 m"]} },
  { id:"spo134", t:"sport", d:7, c:0, en:{q:"Who is the only tennis player to win all four majors and Olympic gold in the same year?",a:["Steffi Graf","Martina Navratilova","Serena Williams","Rod Laver"]}, tr:{q:"Aynı yıl içinde dört büyük tenis turnuvasını ve olimpiyat altınını kazanan tek oyuncu kimdir?",a:["Steffi Graf","Martina Navratilova","Serena Williams","Rod Laver"]} },
  { id:"spo135", t:"sport", d:7, c:0, en:{q:"Which event closes the men's Olympic decathlon?",a:["1500 metres","400 metres","Javelin","Pole vault"]}, tr:{q:"Erkekler olimpiyat dekatlonu hangi branşla sona erer?",a:["1500 metre","400 metre","Cirit atma","Sırıkla atlama"]} },
  { id:"spo136", t:"sport", d:7, c:0, en:{q:"Which town hosted the first Winter Olympic Games, in 1924?",a:["Chamonix","St. Moritz","Lake Placid","Oslo"]}, tr:{q:"1924'teki ilk Kış Olimpiyat Oyunları'na hangi kasaba ev sahipliği yaptı?",a:["Chamonix","St. Moritz","Lake Placid","Oslo"]} },
  { id:"spo137", t:"sport", d:7, c:0, en:{q:"In which season did the NBA first use a three-point line?",a:["1979-80","1966-67","1986-87","1992-93"]}, tr:{q:"NBA üç sayı çizgisini ilk kez hangi sezonda kullandı?",a:["1979-80","1966-67","1986-87","1992-93"]} },
  { id:"spo138", t:"sport", d:7, c:0, en:{q:"Which manufacturer beat Ferrari to win the 1966 Le Mans 24 Hours?",a:["Ford","Porsche","Jaguar","Aston Martin"]}, tr:{q:"1966 Le Mans 24 Saat yarışını Ferrari'yi geçerek hangi üretici kazandı?",a:["Ford","Porsche","Jaguar","Aston Martin"]} },
  { id:"spo139", t:"sport", d:7, c:0, en:{q:"In backgammon, what is the highest number shown on the doubling cube?",a:["64","32","36","100"]}, tr:{q:"Tavlada ikiye katlama zarının üzerindeki en yüksek sayı kaçtır?",a:["64","32","36","100"]} },
  { id:"spo140", t:"sport", d:7, c:0, en:{q:"In darts, how far is the throwing line from the face of the board?",a:["2.37 m","1.98 m","2.74 m","3.05 m"]}, tr:{q:"Dartta atış çizgisi tahtanın yüzeyinden ne kadar uzaktadır?",a:["2,37 m","1,98 m","2,74 m","3,05 m"]} },
  { id:"spo141", t:"sport", d:7, c:0, en:{q:"How long after kick-off did Hakan Şükür score in the 2002 World Cup third-place match?",a:["About 11 seconds","About 25 seconds","About one minute","About two minutes"]}, tr:{q:"2002 Dünya Kupası üçüncülük maçında Hakan Şükür golü başlama vuruşundan ne kadar sonra attı?",a:["Yaklaşık 11 saniye","Yaklaşık 25 saniye","Yaklaşık bir dakika","Yaklaşık iki dakika"]} },
  { id:"spo142", t:"sport", d:7, c:0, en:{q:"In volleyball, which of these is a libero never allowed to do?",a:["Block or attempt to block","Receive a serve","Dig a spike","Play in the back row"]}, tr:{q:"Voleybolda libero şu hareketlerden hangisini asla yapamaz?",a:["Blok yapmak ya da denemek","Servis karşılamak","Smacı savunmak","Arka bölgede oynamak"]} },
  { id:"spo143", t:"sport", d:7, c:0, en:{q:"Who is the only player to win all four Grand Slam singles titles in one year twice?",a:["Rod Laver","Don Budge","Margaret Court","Steffi Graf"]}, tr:{q:"Dört Grand Slam tekler şampiyonluğunu aynı yıl içinde iki kez kazanan tek tenisçi kimdir?",a:["Rod Laver","Don Budge","Margaret Court","Steffi Graf"]} },
  { id:"spo144", t:"sport", d:7, c:0, en:{q:"In which two swimming strokes must the wall be touched with both hands at the same time?",a:["Butterfly and breaststroke","Backstroke and freestyle","Breaststroke and backstroke","Butterfly and freestyle"]}, tr:{q:"Hangi iki yüzme stilinde duvara iki elle aynı anda dokunmak zorunludur?",a:["Kelebek ve kurbağalama","Sırtüstü ve serbest","Kurbağalama ve sırtüstü","Kelebek ve serbest"]} },
  { id:"spo145", t:"sport", d:7, c:0, en:{q:"Which one-day cycling classic is nicknamed 'The Hell of the North'?",a:["Paris-Roubaix","Tour of Flanders","Milan-San Remo","Liège-Bastogne-Liège"]}, tr:{q:"Hangi tek günlük bisiklet klasiği 'Kuzeyin Cehennemi' olarak anılır?",a:["Paris-Roubaix","Flandre Turu","Milano-San Remo","Liège-Bastogne-Liège"]} },
  { id:"spo146", t:"sport", d:7, c:0, en:{q:"In Greco-Roman wrestling, what is banned that freestyle wrestlers are allowed to do?",a:["Taking holds below the waist","Lifting the opponent off the mat","Winning the bout by a pin","Gripping the head and one arm"]}, tr:{q:"Greko-Romen güreşte yasak olan ama serbest güreşte izin verilen hareket hangisidir?",a:["Belden aşağı tutuş yapmak","Rakibi yerden kaldırmak","Maçı tuşla kazanmak","Baş ve tek kolu kavramak"]} },
  { id:"spo147", t:"sport", d:7, c:0, en:{q:"Which figure skating jump is the only one taken off facing forwards?",a:["The Axel","The Salchow","The Lutz","The toe loop"]}, tr:{q:"Artistik patinajda öne dönük şekilde havalanılan tek sıçrama hangisidir?",a:["Axel","Salchow","Lutz","Toe loop"]} },
  { id:"spo148", t:"sport", d:7, k:"tf", v:true, en:{q:"In football, no offside is given if the ball comes directly from a corner, throw-in or goal kick."}, tr:{q:"Futbolda kornerden, taç atışından veya kale vuruşundan doğrudan gelen topta ofsayt verilmez."} },
  { id:"spo149", t:"sport", d:7, k:"tf", v:false, en:{q:"Under FIBA rules, a team must move the ball into the opponents' half within ten seconds."}, tr:{q:"FIBA kurallarına göre bir takım topu rakip yarı sahaya on saniye içinde geçirmek zorundadır."} },
  { id:"spo150", t:"sport", d:7, k:"tf", v:true, en:{q:"Wimbledon used white tennis balls until 1986, when it switched to yellow ones."}, tr:{q:"Wimbledon 1986'ya kadar beyaz tenis topu kullandı ve o yıl sarı toplara geçti."} },
  { id:"spo151", t:"sport", d:7, k:"tf", v:false, en:{q:"In athletics, a javelin throw counts as valid only if the javelin sticks into the ground."}, tr:{q:"Atletizmde bir cirit atışı ancak cirit yere saplanırsa geçerli sayılır."} },
  { id:"spo152", t:"sport", d:7, k:"tf", v:false, en:{q:"The first Olympic flame to burn at a Games was lit in the stadium at Berlin in 1936."}, tr:{q:"Bir olimpiyatta yanan ilk olimpiyat ateşi 1936 Berlin Oyunları'nda stadyumda yakıldı."} },
  { id:"spo153", t:"sport", d:7, k:"tf", v:true, en:{q:"In ski jumping, five judges award style marks and the highest and lowest are discarded."}, tr:{q:"Kayakla atlamada beş hakem stil puanı verir ve en yüksek ile en düşük puan hesaba katılmaz."} },
  { id:"spo154", t:"sport", d:8, c:0, en:{q:"Which flag tells a driver to let the car behind through because he is being lapped?",a:["Blue","Yellow","Green","White"]}, tr:{q:"Turlanan bir pilota arkadaki aracı geçirmesini hangi renk bayrak bildirir?",a:["Mavi","Sarı","Yeşil","Beyaz"]} },
  { id:"spo155", t:"sport", d:8, c:0, en:{q:"In which city did Galatasaray win the 2000 UEFA Cup final?",a:["Copenhagen","Stockholm","Vienna","Amsterdam"]}, tr:{q:"Galatasaray 2000 UEFA Kupası finalini hangi şehirde kazandı?",a:["Kopenhag","Stokholm","Viyana","Amsterdam"]} },
  { id:"spo156", t:"sport", d:8, c:0, en:{q:"Which throwing event is in the men's decathlon but not the women's heptathlon?",a:["Discus","Shot put","Javelin","Hammer"]}, tr:{q:"Hangi atma branşı erkekler dekatlonunda var ama kadınlar heptatlonunda yok?",a:["Disk atma","Gülle atma","Cirit atma","Çekiç atma"]} },
  { id:"spo157", t:"sport", d:8, c:0, en:{q:"Quarantine rules moved the 1956 Melbourne Olympic equestrian events to which city?",a:["Stockholm","Helsinki","Oslo","Copenhagen"]}, tr:{q:"Karantina kuralları 1956 Melbourne Olimpiyatları'nın binicilik yarışlarını hangi şehre taşıdı?",a:["Stokholm","Helsinki","Oslo","Kopenhag"]} },
  { id:"spo158", t:"sport", d:8, c:0, en:{q:"Which Grand Slam tennis event went from grass to clay and then to hard courts?",a:["US Open","Australian Open","French Open","Wimbledon"]}, tr:{q:"Hangi Grand Slam tenis turnuvası çim korttan toprağa, sonra sert korta geçti?",a:["ABD Açık","Avustralya Açık","Fransa Açık","Wimbledon"]} },
  { id:"spo159", t:"sport", d:8, c:0, en:{q:"Against which team did Wilt Chamberlain score 100 points in 1962?",a:["New York Knicks","Boston Celtics","Los Angeles Lakers","St. Louis Hawks"]}, tr:{q:"Wilt Chamberlain 1962'de 100 sayıyı hangi takıma karşı attı?",a:["New York Knicks","Boston Celtics","Los Angeles Lakers","St. Louis Hawks"]} },
  { id:"spo160", t:"sport", d:8, c:0, en:{q:"Who is the only driver to have won the Monaco GP, the Indy 500 and Le Mans?",a:["Graham Hill","Jackie Stewart","Mario Andretti","Juan Pablo Montoya"]}, tr:{q:"Monako GP'yi, Indianapolis 500'ü ve Le Mans'ı kazanan tek pilot kimdir?",a:["Graham Hill","Jackie Stewart","Mario Andretti","Juan Pablo Montoya"]} },
  { id:"spo161", t:"sport", d:8, c:0, en:{q:"Who became the first official world chess champion, in 1886?",a:["Wilhelm Steinitz","Emanuel Lasker","Paul Morphy","José Raúl Capablanca"]}, tr:{q:"1886'da ilk resmî dünya satranç şampiyonu kim oldu?",a:["Wilhelm Steinitz","Emanuel Lasker","Paul Morphy","José Raúl Capablanca"]} },
  { id:"spo162", t:"sport", d:8, c:0, en:{q:"In Go, which rule forbids immediately recreating the previous board position?",a:["The ko rule","Atari","Seki","Komi"]}, tr:{q:"Go oyununda önceki taş diziliminin hemen tekrarlanmasını yasaklayan kural hangisidir?",a:["Ko kuralı","Atari","Seki","Komi"]} },
  { id:"spo163", t:"sport", d:8, c:0, en:{q:"In snooker, what is the highest break possible in a frame with a free ball?",a:["155","147","149","167"]}, tr:{q:"Snooker'da serbest topun kullanıldığı bir framede yapılabilecek en yüksek break kaçtır?",a:["155","147","149","167"]} },
  { id:"spo164", t:"sport", d:8, c:0, en:{q:"In a swimming medley relay, which stroke does the first swimmer use?",a:["Backstroke","Butterfly","Breaststroke","Freestyle"]}, tr:{q:"Karışık bayrak yüzme yarışında ilk yüzücü hangi stilde yüzer?",a:["Sırtüstü","Kelebek","Kurbağalama","Serbest"]} },
  { id:"spo165", t:"sport", d:8, c:0, en:{q:"Table tennis balls were enlarged in 2000 to which diameter?",a:["40 mm","38 mm","42 mm","44 mm"]}, tr:{q:"Masa tenisi topları 2000 yılında hangi çapa büyütüldü?",a:["40 mm","38 mm","42 mm","44 mm"]} },
  { id:"spo166", t:"sport", d:8, c:0, en:{q:"Hakan Şükür's 11-second goal at the 2002 World Cup came in the third-place match against whom?",a:["South Korea","Japan","Brazil","Senegal"]}, tr:{q:"Hakan Şükür'ün 2002 Dünya Kupası'ndaki 11 saniyelik golü, üçüncülük maçında hangi takıma atıldı?",a:["Güney Kore","Japonya","Brezilya","Senegal"]} },
  { id:"spo167", t:"sport", d:8, c:0, en:{q:"Which country won the first FIBA World Championship, held in 1950?",a:["Argentina","United States","Brazil","Soviet Union"]}, tr:{q:"1950'de düzenlenen ilk FIBA Dünya Şampiyonası'nı hangi ülke kazandı?",a:["Arjantin","ABD","Brezilya","Sovyetler Birliği"]} },
  { id:"spo168", t:"sport", d:8, c:0, en:{q:"Under World Athletics rules, how many false starts is a sprinter allowed before disqualification?",a:["None at all","One","Two","Three"]}, tr:{q:"Dünya Atletizm kurallarına göre bir sprinter diskalifiye olmadan kaç hatalı çıkış yapabilir?",a:["Hiç","Bir","İki","Üç"]} },
  { id:"spo169", t:"sport", d:8, c:0, en:{q:"On which apparatus did Nadia Comăneci score the first perfect 10 in Olympic history?",a:["The uneven bars","The balance beam","The floor exercise","The vault"]}, tr:{q:"Nadia Comăneci, olimpiyat tarihinin ilk tam 10 puanını hangi aletten aldı?",a:["Asimetrik paralel","Denge aleti","Yer hareketleri","Atlama masası"]} },
  { id:"spo170", t:"sport", d:8, c:0, en:{q:"What colour marks the softest dry-weather Formula 1 tyre?",a:["Red","White","Yellow","Green"]}, tr:{q:"Kuru hava için en yumuşak Formula 1 lastiği hangi renkle işaretlenir?",a:["Kırmızı","Beyaz","Sarı","Yeşil"]} },
  { id:"spo171", t:"sport", d:8, k:"tf", v:true, en:{q:"In football, if a throw-in goes straight into the thrower's own goal, the other team gets a corner kick."}, tr:{q:"Futbolda taç atışı doğrudan atan takımın kendi kalesine girerse, rakip takıma köşe vuruşu verilir."} },
  { id:"spo172", t:"sport", d:8, k:"tf", v:false, en:{q:"The three-point line in FIBA basketball is further from the basket than the NBA's three-point line."}, tr:{q:"FIBA basketbolunda üç sayı çizgisi, NBA'deki üç sayı çizgisinden potaya daha uzaktır."} },
  { id:"spo173", t:"sport", d:8, k:"tf", v:false, en:{q:"Wimbledon was the first Grand Slam tournament to use a tie-break."}, tr:{q:"Wimbledon, tie-break kuralını kullanan ilk Grand Slam turnuvası olmuştur."} },
  { id:"spo174", t:"sport", d:8, k:"tf", v:true, en:{q:"In athletics, the men's shot put and the men's hammer weigh exactly the same: 7.26 kg."}, tr:{q:"Atletizmde erkekler gülle ile erkekler çekiç tam olarak aynı ağırlıktadır: 7,26 kg."} },
  { id:"spo175", t:"sport", d:8, k:"tf", v:true, en:{q:"Olympic medals were awarded for painting, sculpture and literature at the Games between 1912 and 1948."}, tr:{q:"1912 ile 1948 arasındaki Olimpiyat Oyunları'nda resim, heykel ve edebiyat dallarında da madalya verildi."} },
  { id:"spo176", t:"sport", d:8, k:"tf", v:false, en:{q:"Backstroke swimmers must stay on their back for the whole race, even while turning at the wall."}, tr:{q:"Sırtüstü yüzücüler, duvarda dönüş yaparken bile yarış boyunca sırt üstü kalmak zorundadır."} }
);
